#!/usr/bin/env python3
"""Generate the offline bundle and synchronized documentation using only stdlib."""
import json,re,hashlib,sys
from pathlib import Path
sys.dont_write_bytecode=True
sys.path.insert(0,str(Path(__file__).resolve().parent))
from content import DECK,ROOT,SOURCE_DIR,PACO,PORT,FINAL

def mm(sec):return f'{sec//60}:{sec%60:02}'
def link(s,v=None):return f'index.html#{s["id"]}'+('/'+v['id'] if v else '')
def md(t):return str(t).replace('|','\\|').replace('\n','<br>')
def visual_text(v):
 t=v['type']
 if t in {'equation','parallax'}:return 'Equation: '+v['text']
 if t=='code':return 'Code:\n```text\n'+v['text']+'\n```'
 if t=='education-pillars':return '\n'.join('- **'+stage['name']+' — '+stage['headline']+'**: '+'; '.join(stage['details']) for stage in v['stages'])
 if t=='flow':return 'Diagram: '+' → '.join(v['nodes'])
 if t=='table':return '\n| '+' | '.join(v['headers'])+' |\n| '+' | '.join(['---']*len(v['headers']))+' |\n'+'\n'.join('| '+' | '.join(map(str,row))+' |' for row in v['rows'])
 if t=='image':return f'Media: `{v["file"]}` — {v.get("caption","")}'
 return 'Native HTML/SVG explanation in `app.js`.'

(ROOT/'deck.json').write_text(json.dumps(DECK,ensure_ascii=False,indent=2)+'\n')
public={k:v for k,v in DECK.items() if k!='sources'}
